// Config plugin: FileProvider for the sideloaded APK installer, plus the install-unknown-apps
// permission. android/ is generated by prebuild and never committed, so this has to live here.
const { mkdirSync, writeFileSync } = require('node:fs');
const path = require('node:path');
const { AndroidConfig, withAndroidManifest, withDangerousMod } = require('expo/config-plugins');

const PROVIDER_CLASS = 'expo.modules.apkinstaller.ApkFileProvider';
const AUTHORITY = '${applicationId}.apkinstaller';
const PATHS_RESOURCE = '@xml/apk_installer_paths';
const PATHS_FILE = `<?xml version="1.0" encoding="utf-8"?>
<paths>
  <cache-path name="apk-updates" path="." />
  <files-path name="apk-updates-files" path="." />
</paths>
`;

function ensureProvider(androidManifest) {
  const app = AndroidConfig.Manifest.getMainApplicationOrThrow(androidManifest);
  app.provider = app.provider || [];
  const already = app.provider.some((provider) => provider.$?.['android:name'] === PROVIDER_CLASS);
  if (!already) {
    app.provider.push({
      $: {
        'android:name': PROVIDER_CLASS,
        'android:authorities': AUTHORITY,
        'android:exported': 'false',
        'android:grantUriPermissions': 'true',
      },
      'meta-data': [
        {
          $: {
            'android:name': 'android.support.FILE_PROVIDER_PATHS',
            'android:resource': PATHS_RESOURCE,
          },
        },
      ],
    });
  }
  return androidManifest;
}

function withApkInstaller(config) {
  config = withAndroidManifest(config, (mod) => {
    mod.modResults = ensureProvider(mod.modResults);
    return mod;
  });
  config = withDangerousMod(config, [
    'android',
    async (mod) => {
      const dir = path.join(mod.modRequest.platformProjectRoot, 'app/src/main/res/xml');
      mkdirSync(dir, { recursive: true });
      writeFileSync(path.join(dir, 'apk_installer_paths.xml'), PATHS_FILE);
      return mod;
    },
  ]);
  return config;
}

module.exports = withApkInstaller;
